 private function fintsPayloadSource(string $id,int $version):array{$this->office($this->actor);$r=$this->get($id);if($r['state']!=='approved'||(int)$r['version']!==$version)throw new DomainException('Nur ein aktuell freigegebener Lastschriftauftrag kann über FinTS gesendet werden.');$f=new Finance($this->db,$this->actor);if(!(int)($f->accountSettings($r['account_id'])['fints_write']??0))throw new DomainException('FinTS-Schreiben ist für dieses Einzugskonto noch gesperrt. In den Kontoeinstellungen „Erlaubt“ auswählen.');$s=$this->current($r);$office=$this->office((string)$r['approved_by']);if((int)$office['version']!==(int)$r['office_version'])throw new DomainException('Freigabeamt geändert. Auftrag neu prüfen.');return ['order_id'=>$r['id'],'order_version'=>(int)$r['version'],'account_id'=>$r['account_id'],'source_iban'=>$s['creditor']['iban'],'xml'=>$s['xml'],'reference'=>'FinTS SEPA CORE KH'.$r['id']];}
 /** Mark only a bank-confirmed FinTS result as submitted; no contribution is paid here. */
 public function markFintsSubmitted(string $id,int $version,string $reference,int $attempt=0):void{$reference=trim($reference);if($reference===''||mb_strlen($reference)>200)throw new DomainException('Bankbestätigung prüfen.');$this->tx(function()use($id,$version,$reference,$attempt){$a=$this->access();$this->office($this->actor);$transport=$this->transport($id);if($transport['pending']??false){if($attempt<1||(int)$transport['event']['sequence']!==$attempt||$transport['event']['actor_id']!==$a['id']||(int)$transport['event']['object_version']!==$version)throw new DomainException('Genau den aktuellen offenen FinTS-Ausgang erneut prüfen.',409);}elseif($attempt!==0)throw new DomainException('Genau den aktuellen offenen FinTS-Ausgang erneut prüfen.',409);$r=$this->get($id);if($r['state']!=='approved'||(int)$r['version']!==$version)throw new DomainException('Lastschriftauftrag wurde bereits verarbeitet oder geändert.');if(!($transport['pending']??false)){$this->current($r);$this->office((string)$r['approved_by']);}$this->q("UPDATE sepa_orders SET state='submitted',bank_reference=?,version=version+1 WHERE club_id=? AND id=?",[$reference,$a['club_id'],$id]);$this->audit('sepa.order.fints_submitted',$id,$version+1);});}
 public function approve(string $id,int $version):void{$this->tx(function()use($id,$version){$a=$this->access();$r=$this->get($id);if($r['state']!=='prepared'||(int)$r['version']!==$version)throw new DomainException('Unveränderten vorbereiteten Auftrag wählen.');$this->current($r);$office=$this->office($this->actor);$this->q("UPDATE sepa_orders SET state='approved',approved_by=?,approved_at=?,office_version=?,version=version+1 WHERE club_id=? AND id=?",[$a['id'],gmdate('c'),$office['version'],$a['club_id'],$id]);$this->audit('sepa.order.approved',$id,$version+1);$this->audit('sepa.order.tracking_ready',$id,$version+1);});}
 public function export(string $id,int $version):string{return $this->tx(function()use($id,$version){$a=$this->access();$this->noPendingTransport($id);$r=$this->get($id);if(!in_array($r['state'],['approved','exported'],true)||(int)$r['version']!==$version)throw new DomainException('Zuerst den aktuellen Zahlungsauftrag freigeben.');$s=$this->current($r);if((int)$this->office($r['approved_by'])['version']!==(int)$r['office_version'])throw new DomainException('Freigabeamt geändert.');if($r['state']==='approved'){$this->q("UPDATE sepa_orders SET state='exported',exported_at=?,version=version+1 WHERE club_id=? AND id=?",[gmdate('c'),$a['club_id'],$id]);$this->audit('sepa.order.exported',$id,$version+1);}return $s['xml'];});}
 public function submitted(string $id,int $version,string $reference):void{$reference=trim($reference);if($reference===''||strlen($reference)>200)throw new DomainException('Tatsächliche Bankbestätigung / Auftragsnummer eingeben.');$this->tx(function()use($id,$version,$reference){$a=$this->access();$r=$this->get($id);if($r['state']!=='exported'||(int)$r['version']!==$version)throw new DomainException('Unveränderten exportierten Auftrag auswählen.');$this->q("UPDATE sepa_orders SET state='submitted',bank_reference=?,version=version+1 WHERE club_id=? AND id=?",[$reference,$a['club_id'],$id]);$this->audit('sepa.order.externally_submitted',$id,$version+1);});}
 public function cancel(string $id,int $version):void{$this->tx(function()use($id,$version){$a=$this->access();$this->noPendingTransport($id);$r=$this->get($id);if(!in_array($r['state'],['prepared','approved'],true)||(int)$r['version']!==$version)throw new DomainException('Bereits exportierte Aufträge zuerst bei der Bank klären; nicht still erneut einziehen.');$this->q("UPDATE sepa_orders SET state='cancelled',version=version+1 WHERE club_id=? AND id=?",[$a['club_id'],$id]);$this->q("UPDATE sepa_order_items SET state='cancelled' WHERE club_id=? AND order_id=?",[$a['club_id'],$id]);$this->audit('sepa.order.cancelled',$id,$version+1);});}
 /** A legacy unique whole payment remains supported; ambiguous originals need conscious selection. */
 public function returnFundingReview(string $item,string $transaction,string $reason,?array $allocations=null,?string $document=null):?array{
  return $this->read(function()use($item,$transaction,$reason,$allocations,$document):array{$a=$this->access();$i=$this->q('SELECT i.*,o.account_id,o.state AS order_state FROM sepa_order_items i JOIN sepa_orders o ON o.club_id=i.club_id AND o.id=i.order_id WHERE i.club_id=? AND i.id=?',[$a['club_id'],$item])->fetch();if(!$i||$i['id']!==$item||$i['state']!=='active'||!in_array($i['order_state'],['exported','submitted'],true))throw new DomainException('Aktuellen eingereichten Lastschriftposten auswählen.');$this->noPendingTransport($i['order_id']);$f=new Finance($this->db,$this->actor);
   if($allocations!==null)return ['financial'=>$f->nativeDebitReturnFundingReview($item,$transaction,$allocations,$reason,$this->vault,$document)];
   $entry=$f->currentEntry($i['entry_id']);$t=$f->transactionDetail($transaction,true);$links=array_values(array_filter($f->allocations($i['entry_id'],false,true),static fn(array$l):bool=>$l['voided_at']===null&&$l['reversal_of']===null&&$l['reversed_on']===null));
   if($entry['kind']!=='contribution'||$entry['payment_state']!=='paid'||(int)$entry['amount_cents']!==(int)$i['cents']||count($links)!==1||(int)$links[0]['cents']!==(int)$i['cents'])throw new DomainException('Die tatsächlichen ursprünglichen Einzugszuordnungen bewusst auswählen und gemeinsam mit der Rücklastschrift prüfen.',422);
   $positive=$f->transactionDetail($links[0]['transaction_id'],true);$positiveLinks=array_values(array_filter($f->allocations($positive['id'],true,true),static fn(array$l):bool=>$l['voided_at']===null));if(count($positiveLinks)!==1||(int)$positive['cents']!==(int)$i['cents']||$positive['account_id']!==$i['account_id']||$t['account_id']!==$i['account_id']||(int)$t['cents']!==-(int)$i['cents']||$t['reversal_of']||$t['reversed_on']||(int)$t['allocated_cents']!==0||$t['booked_on']<$positive['booked_on'])throw new DomainException('Die tatsächlichen ursprünglichen Einzugszuordnungen bewusst auswählen und gemeinsam mit der Rücklastschrift prüfen.',422);return [];
  })['financial']??null;
 }
 public function recordReturn(string $item,string $transaction,string $reason,?string $document=null,?array $allocations=null,?string $nativeKey=null,?string $financialHash=null):?array{
  $rawReason=$reason;$reason=trim($reason);if($reason===''||!mb_check_encoding($reason,'UTF-8')||mb_strlen($reason,'UTF-8')>500)throw new DomainException('Rücklastschriftgrund mit höchstens 500 Zeichen angeben.');$outcome=$this->tx(function()use($item,$transaction,$reason,$rawReason,$document,$allocations,$nativeKey,$financialHash){$a=$this->access();$i=$this->q('SELECT i.*,o.account_id,o.state order_state FROM sepa_order_items i JOIN sepa_orders o ON o.club_id=i.club_id AND o.id=i.order_id WHERE i.club_id=? AND i.id=?',[$a['club_id'],$item])->fetch();if(!$i||$i['state']!=='active'||!in_array($i['order_state'],['exported','submitted'],true))throw new DomainException('Aktuellen eingereichten Lastschriftposten auswählen.');$f=new Finance($this->db,$this->actor);$t=$f->transactionDetail($transaction,true);if($t['account_id']!==$i['account_id']||(int)$t['cents']!==-(int)$i['cents']||$t['reversal_of']||$t['reversed_on']||$t['allocated_cents'])throw new DomainException('Unzugeordneten Rücklastschriftumsatz auf demselben Konto und mit genauem Einzugsbetrag auswählen. Gebühren separat erfassen.');if($document)(new Documents($this->db,$this->actor))->currentFinancialDocument($document);
   $this->returnFundingReview($item,$transaction,$rawReason,$allocations,$document);if($allocations!==null){if($nativeKey===null||$financialHash===null)throw new DomainException('Ursprüngliche Rücklastschriftzuordnungen aktuell prüfen und gesondert bestätigen.',422);$financial=$f->recordNativeDebitFundingLocked($item,$transaction,$allocations,$rawReason,$document,$nativeKey,$financialHash,$this->vault);return ['entry'=>$i['entry_id'],'financial'=>$financial];}
   $links=array_values(array_filter($f->allocations($i['entry_id'],false,true),fn($l)=>!$l['voided_at']&&!$l['reversed_on']&&!$l['reversal_of']));
   if(count($links)===1&&(int)$links[0]['cents']===(int)$i['cents']){
    $positive=$f->transactionDetail($links[0]['transaction_id'],true);$positiveLinks=array_values(array_filter($f->allocations($positive['id'],true,true),fn($l)=>!$l['voided_at']));
    if(count($positiveLinks)===1&&(int)$positive['cents']===(int)$i['cents']&&$positive['account_id']===$i['account_id'])$f->reconcileReturnedDebitLocked($i['entry_id'],$positive['id'],$transaction,$reason);
   }
   $record=['club_id'=>$a['club_id'],'id'=>bin2hex(random_bytes(16)),'item_id'=>$item,'transaction_id'=>$transaction,'reason'=>$reason,'document_id'=>$document,'actor_id'=>$a['id'],'created_at'=>gmdate('c')];
   if(NativeDebitReturnHistory::available($this->db)){$actual=$f->transactionDetail($transaction,true);$f->recordNativeDebitLegacyEventLocked($record,$nativeKey??bin2hex(random_bytes(16)),['reason'=>$reason,'entry_id'=>$i['entry_id'],'counter'=>$actual],$actual['reversal_of']);}
   else $this->q('INSERT INTO sepa_return_records VALUES(?,?,?,?,?,?,?,?)',array_values($record));$this->q("UPDATE sepa_order_items SET state='returned' WHERE club_id=? AND id=?",[$a['club_id'],$item]);$this->audit('sepa.return.recorded',$item,1);
   return ['entry'=>$i['entry_id'],'financial'=>null];
  });DonationPreparation::afterSource($this->db,$this->actor,'entry',$outcome['entry']);return $outcome['financial'];
 }
 public static function xml(array $s):string{
  $d=new DOMDocument('1.0','UTF-8');$d->formatOutput=true;$ns='urn:iso:std:iso:20022:tech:xsd:pain.008.001.08';$root=$d->createElementNS($ns,'Document');$d->appendChild($root);$add=static function($parent,string $name,?string $value=null)use($d,$ns){$n=$d->createElementNS($ns,$name);if($value!==null)$n->appendChild($d->createTextNode($value));$parent->appendChild($n);return $n;};
  $init=$add($root,'CstmrDrctDbtInitn');$header=$add($init,'GrpHdr');$add($header,'MsgId','KH'.$s['id']);$add($header,'CreDtTm',$s['created_at']);$add($header,'NbOfTxs',(string)count($s['items']));$add($header,'CtrlSum',Finance::decimal($s['total_cents']));$add($add($header,'InitgPty'),'Nm',mb_substr($s['creditor']['holder'],0,70));
  $payment=$add($init,'PmtInf');$add($payment,'PmtInfId','KH'.$s['id']);$add($payment,'PmtMtd','DD');$add($payment,'BtchBookg','false');$add($payment,'NbOfTxs',(string)count($s['items']));$add($payment,'CtrlSum',Finance::decimal($s['total_cents']));$type=$add($payment,'PmtTpInf');$add($add($type,'SvcLvl'),'Cd','SEPA');$add($add($type,'LclInstrm'),'Cd','CORE');$add($type,'SeqTp','RCUR');$add($payment,'ReqdColltnDt',$s['collection_date']);
  $add($add($payment,'Cdtr'),'Nm',mb_substr($s['items'][0]['mandate']['terms']['creditor_name'],0,70));$add($add($add($payment,'CdtrAcct'),'Id'),'IBAN',$s['creditor']['iban']);$add($add($add($add($payment,'CdtrAgt'),'FinInstnId'),'Othr'),'Id','NOTPROVIDED');$add($payment,'ChrgBr','SLEV');
  $other=$add($add($add($add($payment,'CdtrSchmeId'),'Id'),'PrvtId'),'Othr');$add($other,'Id',$s['items'][0]['mandate']['terms']['creditor_id']);$add($add($other,'SchmeNm'),'Prtry','SEPA');
  foreach($s['items'] as $index=>$item){$m=$item['mandate'];$tx=$add($payment,'DrctDbtTxInf');$add($add($tx,'PmtId'),'EndToEndId','KH'.substr($s['id'],0,24).'-'.($index+1));$amount=$add($tx,'InstdAmt',Finance::decimal($item['cents']));$amount->setAttribute('Ccy','EUR');$mandate=$add($add($tx,'DrctDbtTx'),'MndtRltdInf');$add($mandate,'MndtId',$m['reference']);$add($mandate,'DtOfSgntr',$m['signed_on']);$add($mandate,'AmdmntInd','false');$add($add($add($add($tx,'DbtrAgt'),'FinInstnId'),'Othr'),'Id','NOTPROVIDED');$add($add($tx,'Dbtr'),'Nm',mb_substr($m['bank']['holder'],0,70));$add($add($add($tx,'DbtrAcct'),'Id'),'IBAN',$m['bank']['iban']);$add($add($tx,'RmtInf'),'Ustrd',mb_substr($item['number'].' Mitgliedsbeitrag',0,140));}
  $errors=libxml_use_internal_errors(true);try{if(!$d->schemaValidate(dirname(dirname(__DIR__, 2),2).'/banking/schemas/pain.008.001.08.xsd'))throw new DomainException('Die erzeugte Bankdatei entspricht nicht dem SEPA-Format. Der Auftrag wurde nicht erstellt.');}finally{libxml_clear_errors();libxml_use_internal_errors($errors);}
  return $d->saveXML();
 }
